import static org.junit.Assert.assertEquals;

public class LocalDateTime_fromCalendarFields_TriageGen1Test {



    @Test
    public void testFromCalendarFields_AD_Era() {
        Calendar calendar = new GregorianCalendar();
        calendar.set(Calendar.ERA, GregorianCalendar.AD);
        calendar.set(Calendar.YEAR, 2023);
        calendar.set(Calendar.MONTH, Calendar.OCTOBER); // 9
        calendar.set(Calendar.DAY_OF_MONTH, 25);
        calendar.set(Calendar.HOUR_OF_DAY, 14);
        calendar.set(Calendar.MINUTE, 30);
        calendar.set(Calendar.SECOND, 45);
        calendar.set(Calendar.MILLISECOND, 123);

        LocalDateTime result = LocalDateTime.fromCalendarFields(calendar);

        assertEquals(2023, result.getYear());
        assertEquals(10, result.getMonthOfYear());
        assertEquals(25, result.getDayOfMonth());
        assertEquals(14, result.getHourOfDay());
        assertEquals(30, result.getMinuteOfHour());
        assertEquals(45, result.getSecondOfMinute());
        assertEquals(123, result.getMillisOfSecond());
    }




}

